fn cb_llvm_llvm_56(s: &mut Scan<'_, '_>, m: &Match<'_>) -> Result<(), LexError> {
    if contains(SET_68, m.group(0)) {
        s.token(T::KEYWORD_TYPE, m.text());
    } else {
        if contains(SET_69, m.group(0)) {
            s.token(T::KEYWORD, m.text());
        } else {
            if contains(SET_70, m.group(0)) {
                s.token(T::KEYWORD, m.text());
            } else {
                s.token(T::ERROR, m.text());
            }
        }
    }
    Ok(())
}

